import { Order } from './types';

export interface OrderPosition { createdAt: string; id: string }

function compareKey(a: OrderPosition, b: OrderPosition): number {
  return a.createdAt < b.createdAt ? -1 : a.createdAt > b.createdAt ? 1 : a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

export class OrderRepository {
  constructor(private readonly rows: Order[]) {}
  /**
   * Returns the tenant's orders sorted ascending by (createdAt, id).
   * When `after` is given, only orders strictly after that pair are returned.
   * Filtering happens on a copy; neither the input array nor rows are mutated.
   */
  list(tenant: string, after?: OrderPosition): Order[] {
    return this.rows
      .filter(row => row.tenant === tenant && (after === undefined || compareKey(row, after) > 0))
      .sort(compareKey);
  }
}
EOF
cat > src/handler.ts <<'EOF'
import { OrderPosition, OrderRepository } from './repository';
import { ListRequest, Page } from './types';

function invalid(): never {
  throw new Error('invalid request');
}

function parseCursor(cursor: unknown): OrderPosition | undefined {
  if (cursor === undefined) return undefined;
  if (typeof cursor !== 'string') invalid();
  const parts = cursor.split('|');
  if (parts.length !== 2 || !parts[0] || !parts[1]) invalid();
  return { createdAt: parts[0], id: parts[1] };
}

export class OrderHandler {
  constructor(private readonly repository: OrderRepository) {}
  list(request: ListRequest): Page {
    if (typeof request.tenant !== 'string' || !request.tenant || !Number.isInteger(request.limit) || request.limit < 1 || request.limit > 100) {
      invalid();
    }
    const after = parseCursor(request.cursor);
    const matching = this.repository.list(request.tenant, after);
    const items = matching.slice(0, request.limit);
    const last = items[items.length - 1];
    const nextCursor = matching.length > request.limit && last ? `${last.createdAt}|${last.id}` : null;
    return { items, nextCursor };
  }
}
EOF
cat >> checks/public.cjs <<'EOF'

// Cursor pagination
{
  const rows = [
    { id: 'c', tenant: 't', createdAt: '2026-01-01', total: 1 },
    { id: 'a', tenant: 't', createdAt: '2026-01-01', total: 1 },
    { id: 'b', tenant: 'o', createdAt: '2026-01-01', total: 1 },
    { id: 'b2', tenant: 't', createdAt: '2026-01-01', total: 1 },
    { id: 'z', tenant: 't', createdAt: '2026-01-02', total: 1 },
    { id: 'y', tenant: 'o', createdAt: '2026-01-03', total: 1 }
  ];
  const snapshot = JSON.parse(JSON.stringify(rows));
  const h = new OrderHandler(new OrderRepository(rows));
  const seen = [];
  let cursor;
  for (;;) {
    const page = h.list({ tenant: 't', limit: 2, cursor });
    seen.push(...page.items.map(x => x.id));
    if (!page.nextCursor) break;
    cursor = page.nextCursor;
  }
  assert.deepEqual(seen, ['a', 'b2', 'c', 'z']);
  assert.deepEqual(h.list({ tenant: 't', limit: 2 }).nextCursor, '2026-01-01|b2');
  // exact fit -> null
  assert.equal(h.list({ tenant: 't', limit: 4 }).nextCursor, null);
  // deleted row / other tenant cursor resumes strictly after the pair
  assert.deepEqual(h.list({ tenant: 't', limit: 10, cursor: '2026-01-01|b' }).items.map(x => x.id), ['b2', 'c', 'z']);
  assert.deepEqual(h.list({ tenant: 't', limit: 10, cursor: '2026-01-02|z' }), { items: [], nextCursor: null });
  assert.deepEqual(h.list({ tenant: 'o', limit: 1, cursor: '2026-01-01|b' }), { items: [rows[5]], nextCursor: null });
  for (const bad of ['', '|', 'a|', '|a', 'a', 'a|b|c']) {
    assert.throws(() => h.list({ tenant: 't', limit: 1, cursor: bad }), /invalid request/);
  }
  for (const limit of [0, 101, 1.5, NaN, '5']) {
    assert.throws(() => h.list({ tenant: 't', limit }), /invalid request/);
  }
  assert.throws(() => h.list({ tenant: '', limit: 1 }), /invalid request/);
  assert.deepEqual(rows, snapshot);
  assert.deepEqual(h.list({ tenant: 't', limit: 100 }).items.length, 4);
}
console.log('public checks passed');
EOF
tsc -p tsconfig.json && node checks/public.cjs

